package cn.emigo.mossdoom;

import com.fasterxml.jackson.databind.JsonNode;
import java.time.OffsetDateTime;
import java.util.*;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.http.ResponseEntity;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api")
class ManagementController {
    private final CatalogService catalog;private final ClientService clients;private final JdbcTemplate db,business;private final AuditService audit;private final ObjectStore store;
    ManagementController(CatalogService c,ClientService cl,JdbcTemplate db,@Qualifier("businessJdbc") JdbcTemplate b,AuditService a,ObjectStore s){catalog=c;clients=cl;this.db=db;business=b;audit=a;store=s;}
    @GetMapping("/platforms") Object platforms(){return catalog.platforms();}
    @PostMapping("/platforms") @PreAuthorize("hasRole('ADMIN')") Object platform(@RequestBody JsonNode b){return catalog.createPlatform(b);}
    @PostMapping("/platforms/{id}/guide") @PreAuthorize("hasRole('ADMIN')") Object platformGuide(@PathVariable UUID id,@RequestBody JsonNode b){return catalog.updateGuide(id,b);}
    @GetMapping({"/sources","/datasets","/batches","/audits","/jobs"}) Object list(jakarta.servlet.http.HttpServletRequest request,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="") String state,@RequestParam(defaultValue="") String cursor,@RequestParam(defaultValue="20") int limit){return catalog.list(request.getRequestURI().substring(5),q,state,cursor,limit);}
    @PostMapping("/sources") @PreAuthorize("hasRole('ADMIN')") Object source(@RequestBody JsonNode b){return catalog.createSource(b);}
    @PostMapping("/datasets") @PreAuthorize("hasRole('ADMIN')") Object dataset(@RequestBody JsonNode b){return catalog.createDataset(b);}
    @GetMapping("/datasets/{id}") Object dataset(@PathVariable UUID id){return catalog.datasetDetail(id);}
    @PostMapping({"/sources/{id}/state","/datasets/{id}/state"}) @PreAuthorize("hasRole('ADMIN')") Object state(@PathVariable UUID id,@RequestBody JsonNode b,jakarta.servlet.http.HttpServletRequest request){return catalog.setState(request.getRequestURI().startsWith("/api/sources/")?"sources":"datasets",id,b);}
    @PostMapping("/sources/bulk-state") @PreAuthorize("hasRole('ADMIN')") Object bulk(@RequestBody JsonNode body){JsonNode items=body.path("items");if(!items.isArray()||items.isEmpty()||items.size()>100)throw DomainSupport.invalid("批量操作每次支持1至100条明确选中的记录");String state=DomainSupport.required(body,"state",16);List<Map<String,Object>> result=new ArrayList<>();for(JsonNode item:items){String id=DomainSupport.required(item,"id",36);try{var command=item.deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)command).put("state",state);catalog.setState("sources",DomainSupport.id(id),command);result.add(Map.of("id",id,"ok",true));}catch(org.springframework.web.server.ResponseStatusException e){result.add(Map.of("id",id,"ok",false,"message",Objects.requireNonNullElse(e.getReason(),"操作失败")));}}return Map.of("items",result);}
    @PostMapping("/datasets/{id}/{kind:schemas|mappings}") @PreAuthorize("hasRole('ADMIN')") Object version(@PathVariable UUID id,@PathVariable String kind,@RequestBody JsonNode b){return catalog.createVersion(id,kind,b);}
    @PostMapping("/datasets/{id}/{kind:schemas|mappings}/{version}/publish") @PreAuthorize("hasRole('ADMIN')") Object publish(@PathVariable UUID id,@PathVariable String kind,@PathVariable int version){return catalog.publishVersion(id,kind,version);}
    @PostMapping("/datasets/{id}/clients") @PreAuthorize("hasRole('ADMIN')") Object createClient(@PathVariable UUID id,@RequestBody JsonNode b){return clients.create(id,b);}
    @PostMapping("/clients/{id}/disable") @PreAuthorize("hasRole('ADMIN')") Object disableClient(@PathVariable UUID id){return clients.disable(id);}
    @GetMapping("/overview") Object overview(){
        Map<String,Object> counts=new LinkedHashMap<>();for(String[] pair:new String[][]{{"platforms","platform"},{"sources","source_instance"},{"datasets","dataset"},{"batches","ingest_batch"}})counts.put(pair[0],db.queryForObject("SELECT count(*) FROM "+pair[1]+" WHERE tenant_id=?",Long.class,DomainSupport.TENANT));
        counts.put("activeSources",db.queryForObject("SELECT count(*) FROM source_instance WHERE tenant_id=? AND state='ACTIVE'",Long.class,DomainSupport.TENANT));
        counts.put("pending",db.queryForObject("SELECT count(*) FROM outbox_job WHERE tenant_id=? AND state IN ('PENDING','RETRY','PROCESSING')",Long.class,DomainSupport.TENANT));
        counts.put("rejected",db.queryForObject("SELECT coalesce(sum(rejected_count),0) FROM ingest_batch WHERE tenant_id=?",Long.class,DomainSupport.TENANT));
        counts.put("applied",db.queryForObject("SELECT coalesce(sum(applied_count),0) FROM ingest_batch WHERE tenant_id=?",Long.class,DomainSupport.TENANT));
        var daily=db.queryForList("SELECT to_char(d.day_value,'MM-DD') AS day,count(b.id) batches,coalesce(sum(b.event_count),0) events FROM generate_series((now() AT TIME ZONE 'Asia/Shanghai')::date-6,(now() AT TIME ZONE 'Asia/Shanghai')::date,interval '1 day') d(day_value) LEFT JOIN ingest_batch b ON b.tenant_id=? AND (b.received_at AT TIME ZONE 'Asia/Shanghai')::date=d.day_value::date GROUP BY d.day_value ORDER BY d.day_value",DomainSupport.TENANT);
        return Map.of("counts",counts,"daily",daily,"recent",catalog.list("batches","","","",5),"environment","test","sourceCallsEnabled",false,"businessModulesEnabled",false,"serverTime",OffsetDateTime.now().toString());
    }
    @GetMapping("/batches/{id}") Object batch(@PathVariable UUID id,@RequestParam(defaultValue="-1") int after){var b=catalog.find("ingest_batch",id);Map<String,Object> result=new LinkedHashMap<>(DomainSupport.row(b));var rows=db.queryForList("SELECT id,ordinal,event_id,entity_key,status,error_code,error_detail,updated_at FROM raw_event WHERE tenant_id=? AND batch_id=? AND received_at=? AND ordinal>? ORDER BY ordinal LIMIT 51",DomainSupport.TENANT,id,b.get("received_at"),after);boolean more=rows.size()>50;var items=rows.subList(0,Math.min(50,rows.size()));result.put("events",items.stream().map(DomainSupport::row).toList());result.put("nextOrdinal",more?items.getLast().get("ordinal"):null);result.put("job",db.queryForList("SELECT id,state,attempts,last_error,available_at,updated_at FROM outbox_job WHERE tenant_id=? AND batch_id=?",DomainSupport.TENANT,id).stream().map(DomainSupport::row).findFirst().orElse(Map.of()));return result;}
    @GetMapping("/batches/{id}/raw") @PreAuthorize("hasRole('ADMIN')") ResponseEntity<byte[]> raw(@PathVariable UUID id){var b=catalog.find("ingest_batch",id);byte[] bytes=store.get((String)b.get("object_key"));if(!DomainSupport.sha(bytes).equals(b.get("object_sha256")))throw DomainSupport.conflict("原文校验失败，已停止读取");audit.record("RAW_READ","batch",id,Map.of("bytes",bytes.length));return ResponseEntity.ok().header("Content-Type","application/json").header("Content-Disposition","attachment; filename=batch-"+id+".json").body(bytes);}
    @PostMapping("/batches/{id}/retry") @PreAuthorize("hasRole('ADMIN')") Object retry(@PathVariable UUID id){catalog.find("ingest_batch",id);int updated=db.update("UPDATE outbox_job SET state='PENDING',attempts=0,available_at=now(),last_error=NULL,updated_at=now() WHERE tenant_id=? AND batch_id=? AND state IN ('FAILED','RETRY')",DomainSupport.TENANT,id);if(updated!=1)throw DomainSupport.conflict("仅可重试处理失败或等待重试的批次；校验失败需修正数据或规则后重新提交");audit.record("BATCH_RETRY","batch",id,Map.of());return Map.of("ok",true);}
    @GetMapping("/quarantine") Object quarantine(@RequestParam(defaultValue="") String cursor,@RequestParam(defaultValue="20") int limit){limit=Math.min(Math.max(limit,1),100);List<Object> values=new ArrayList<>(List.of(DomainSupport.TENANT));String sql="SELECT r.id,r.batch_id,r.received_at,r.event_id,r.entity_key,r.status,r.error_code,r.error_detail,d.name dataset_name,s.name source_name FROM raw_event r JOIN ingest_batch b ON b.id=r.batch_id JOIN dataset d ON d.id=b.dataset_id JOIN source_instance s ON s.id=b.source_id WHERE r.tenant_id=? AND r.status='QUARANTINED'";if(!cursor.isBlank()){sql+=" AND (r.received_at,r.id)<(?::timestamptz,?::uuid)";values.addAll(Arrays.asList(DomainSupport.cursor(cursor)));}sql+=" ORDER BY r.received_at DESC,r.id DESC LIMIT ?";values.add(limit+1);return DomainSupport.page(db.queryForList(sql,values.toArray()),limit,"received_at");}
    @GetMapping("/datasets/{id}/projections") Object projections(@PathVariable UUID id,@RequestParam(defaultValue="") String cursor,@RequestParam(defaultValue="20") int limit){catalog.find("dataset",id);limit=Math.min(Math.max(limit,1),100);List<Object> values=new ArrayList<>(List.of(DomainSupport.TENANT,id));String sql="SELECT *,payload::text AS payload_text FROM standard_event_projection WHERE tenant_id=? AND dataset_id=?";if(!cursor.isBlank()){sql+=" AND (created_at,id)<(?::timestamptz,?::uuid)";values.addAll(Arrays.asList(DomainSupport.cursor(cursor)));}values.add(limit+1);return DomainSupport.page(business.queryForList(sql+" ORDER BY created_at DESC,id DESC LIMIT ?",values.toArray()),limit,"created_at");}
}
